.cg-rail-menu-error-glyph { flex: none; display: grid; place-items: center; width: 16px; height: 16px; color: #c8372b; }

.cg-rail-menu-error-glyph svg { width: 14px; height: 14px; }

.cg-rail-menu-error-text { min-width: 0; flex: 1 1 auto; display: flex; flex-direction: column; gap: 1px; }

.cg-rail-menu-error-name { font-size: 12px; line-height: 16px; color: #8a2c22; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

