body[data-ds-dark-theme] .cg-rail-menu-error-glyph { color: #e26a5c; }

body[data-ds-dark-theme] .cg-rail-menu-error-name { color: #e8b6ae; }

body[data-ds-dark-theme] .cg-rail-menu-error-target,body[data-ds-dark-theme] .cg-rail-menu-error-why { color: #b08a84; }

