/* Match the visible footprint of 20px Lottie artwork and 24-unit icons. */

.cg-rail > .cg-rail-item svg { width: 20px; height: 20px; display: block; flex: none; }



.cg-pins-toggle { margin-top: 0; }

.cg-section-toggle { color: #5f6368; font-size: 14px; line-height: 22px; }

.cg-task-row { position: relative; height: 36px; border-radius: 10px; margin-inline: -6px; margin-bottom: 0; transition: background-color 150ms cubic-bezier(.22, .8, .28, 1); }

.cg-task-row:hover, .cg-task-current { background: var(--cg-hover); }

.cg-task-row .cg-pinned-row { padding: 6px 8px; border-radius: 10px; color: var(--cg-text); font-size: 13px; height: 36px; }

/* Room for the action strip: 27px per button plus the 4px offset, so 93px for pin+archive+more

   and 120px once an archived row adds delete. */

.cg-task-row:hover .cg-pinned-row { padding-right: 93px; background: transparent; }

.cg-task-actions { display: none; position: absolute; right: 4px; top: 2px; }

.cg-task-row:hover .cg-task-actions, .cg-task-row:focus-within .cg-task-actions { display: flex; }

.cg-task-actions .cg-button { width: 27px; height: 27px; padding: 5px; color: var(--cg-muted); }

/* An archived row carries one extra action (delete), so its title keeps more room clear. */

.cg-task-row.cg-task-archived:hover .cg-pinned-row { padding-right: 120px; }

.cg-task-actions .cg-purge-action:hover svg { color: #d4380d; }

/* A pinned row's pin stays tinted, so the row state is readable without opening the menu. */

.cg-task-actions .cg-pin-on { color: #3982fa; }

body[data-ds-dark-theme] .cg-task-actions .cg-pin-on { color: #6b9fff; }

.cg-task-menu .cg-purge-action { color: #c54545; }

/* Child sessions: two groups disclosed independently under a spawning row, children indent one

   step per level. Each header carries its own label and count, so the two never read alike. */

.cg-task-row.cg-task-with-children > .cg-pinned-row,

.cg-task-row.cg-task-child > .cg-pinned-row { padding-left: calc(22px + var(--cg-branch-indent, 0px)); }

/* The chevron is absolutely positioned on purpose: the row is a fixed 31px box, not a flex

   container, so an inline button would push the full-width title onto a second line. The title

   reserves its space through the padding rule above instead. */

.cg-children-toggle { position: absolute; left: 4px; top: 6px; z-index: 1; display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 19px; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--cg-muted); cursor: pointer; }

.cg-children-toggle:hover { color: var(--cg-text); }

.cg-children-toggle svg { transition: transform 150ms ease; }

.cg-children-toggle[aria-expanded="true"] svg { transform: rotate(90deg); }

.cg-task-row.cg-task-child > .cg-children-toggle { left: calc(4px + var(--cg-branch-indent, 0px)); }

/* Status marker for a top-level row: waiting / running / done, and nothing at all when idle.

   It owns the row's leftmost slot, so a row that has a chevron pushes that chevron right and the

   title reserves room for both — the row is a fixed 31px box, not a flex container, so anything

   laid out inline would push the full-width title onto a second line (see the chevron note above).

   Colours come from the host's semantic tokens, so both themes follow without a second rule. */

.cg-task-status { position: absolute; left: 4px; top: 50%; translate: 0 -50%; z-index: 1; display: block; width: 14px; height: 14px; pointer-events: none; }

.cg-task-status[data-state='waiting'],

.cg-task-status[data-state='done'] { width: 10px; height: 10px; left: 6px; }

.cg-task-status[data-state='waiting']::after,

.cg-task-status[data-state='done']::after { content: ''; position: absolute; inset: 20%; border-radius: 50%; background: currentColor; }

.cg-task-status[data-state='waiting'] { color: var(--dsw-alias-state-warn-primary); }

.cg-task-status[data-state='done'] { color: var(--dsw-alias-state-success-primary); }

/* Running is the only moving marker: a quiet ring with a bright arc turning over it. */

.cg-task-status[data-state='running'] { color: var(--dsw-alias-label-tertiary); }

.cg-task-status[data-state='running']::before,

.cg-task-status[data-state='running']::after { content: ''; position: absolute; inset: 0; border: 2px solid currentColor; border-radius: 50%; }

.cg-task-status[data-state='running']::before { opacity: .25; }

.cg-task-status[data-state='running']::after { border-color: transparent; border-top-color: currentColor; animation: cg-status-spin 1.5s linear infinite; }

@keyframes cg-status-spin { to { transform: rotate(360deg); } }

/* This sheet carries the reduced-motion branch for every other animation it owns, and a marker that

   turns forever is precisely what that branch is for. The arc stays as a still segment so the state

   is still readable without the motion. */

@media (prefers-reduced-motion: reduce) {

  /* `animation: none` alone is enough: the element then falls back to the base declarations on

     `::after` above, which already carry the transparent sides plus the currentColor top edge. */

  .cg-task-status[data-state='running']::after { animation: none; }

  .cg-task-status[data-state='running']::before { opacity: .35; }

}

/* Markers appear on top-level rows and on branch rows, but never on agent-spawned rows. That middle

   case is the point: a Session that starts running is reparented under its spawner, so the row you

   most want to watch is exactly the one that lives as a branch, and skipping every child row meant

   skipping it. The child variants below add the branch indent on top, because such a row already

   reserves room for its own chevron and the guide line. */

.cg-task-row.cg-task-stated:not(.cg-task-child) > .cg-children-toggle { left: 22px; }

/* `:not(.cg-task-with-children)` earns its place here: without it this rule ties with the child /

   with-children padding rule at (0,3,0) and wins only by appearing later in the sheet. A row that

   ever carried both classes would then silently lose its indent — exactly the kind of

   ordering-dependent outcome that breaks the day somebody reorders these blocks. With the negation

   the rule stands on its own at (0,4,0) and is disjoint from the with-children variant below. */

.cg-task-row.cg-task-stated:not(.cg-task-child):not(.cg-task-with-children) > .cg-pinned-row { padding-left: 22px; }

.cg-task-row.cg-task-stated:not(.cg-task-child).cg-task-with-children > .cg-pinned-row { padding-left: 40px; }

.cg-task-row.cg-task-stated.cg-task-child > .cg-children-toggle { left: calc(22px + var(--cg-branch-indent, 0px)); }

.cg-task-row.cg-task-stated.cg-task-child > .cg-pinned-row { padding-left: calc(40px + var(--cg-branch-indent, 0px)); }

.cg-group-toggle { box-sizing: border-box; display: flex; align-items: center; gap: 6px; width: calc(100% + 12px); height: 24px; margin: 0 -6px 2px; padding: 2px 8px 2px calc(22px + var(--cg-branch-indent, 0px)); border: 0; border-radius: 8px; background: none; color: var(--cg-muted); font: inherit; font-size: 12px; line-height: 18px; text-align: left; cursor: pointer; }

.cg-group-toggle:hover { background: var(--cg-hover); color: var(--cg-text); }

.cg-group-toggle svg { flex: none; transition: transform 150ms ease; }

.cg-group-toggle[aria-expanded="true"] svg { transform: rotate(90deg); }

.cg-group-label { flex: 1 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

.cg-group-badge { flex: none; min-width: 17px; padding: 0 5px; border-radius: 9px; background: var(--cg-hover); color: var(--cg-muted); font-size: 11px; line-height: 15px; text-align: center; }

.cg-group-more { box-sizing: border-box; display: block; width: calc(100% + 12px); margin: 0 -6px 3px; padding: 2px 8px 2px calc(22px + var(--cg-branch-indent, 0px)); border: 0; border-radius: 8px; background: none; color: var(--cg-muted); font: inherit; font-size: 12px; line-height: 18px; text-align: left; cursor: pointer; }

.cg-group-more:hover { background: var(--cg-hover); color: var(--cg-text); }

.cg-task-row.cg-task-child::before { content: ''; position: absolute; left: calc(10px + var(--cg-branch-indent, 0px)); top: 0; bottom: 0; width: 1px; background: var(--cg-hover); }

/* The shared entrance animation ([role="tooltip"] -> cg-soft-in) animates transform, and an animated
   transform outranks the inline translate(x, y) that positions this card. During its 160 ms the card
   painted at left:0/top:0 and then jumped into place — the flash at the window corner. The card
   positions itself on every show, so it needs no entrance animation; the 190 ms transform transition
   below still makes it glide between rows. */
html[data-chatgpt-ui] .cg-task-preview-floating { animation: none !important; }
html[data-chatgpt-ui] .cg-rail-tooltip { animation: none !important; }
.cg-task-preview { width: 300px; padding: 10px; box-sizing: border-box; z-index: 50; background: var(--cg-page); border: 1px solid #dbdce1; border-radius: 15px; box-shadow: 0 5px 12px #00000012; color: var(--cg-text); font-size: 13px; pointer-events: none; }

/* The floating card is one element for the whole list. It is positioned by `transform`, which the

   browser animates, so it slides after the pointer instead of being rebuilt (and its entrance

   replayed) on every row. Hidden by opacity + visibility, since `display` cannot be transitioned. */

/* No transform transition on purpose. The card is positioned with translate() from left: 0; top: 0, so animating the transform made a freshly created card fly in from the window's top-left corner on the first hover of a session — the flash. Only opacity animates now; position changes land instantly. */
.cg-task-preview-floating { position: fixed; left: 0; top: 0; opacity: 0; visibility: hidden; transition: transform 190ms cubic-bezier(.22, .8, .28, 1), opacity 140ms cubic-bezier(.22, .8, .28, 1), visibility 0s linear 140ms; }

.cg-task-preview-floating[data-on="true"] { opacity: 1; visibility: visible; transition: transform 190ms cubic-bezier(.22, .8, .28, 1), opacity 120ms cubic-bezier(.22, .8, .28, 1); }

/* The generic entrance animation above matches this card through `[role="tooltip"]` and its
   keyframes animate `transform` — which overrides the inline `translate(x, y)` for 160 ms, so the
   card painted at left:0/top:0 and then jumped into place. That was the flash. The card positions
   itself every time it is shown, so it needs no entrance animation at all. */
/* Same reason, one more element: the rail button's name label is a 
ole="tooltip" too, and it is
   positioned with 	ransform: translateY(-50%) translateX(-4px) (line ~907). The shared entrance
   animation overwrote that transform, so during its 160 ms the label sat 4 px low and then snapped up.
   It is normally hidden, which is why this only ever showed up right after mount. */
.cg-task-preview > div { display: flex; align-items: center; gap: 8px; margin-top: 6px; }

.cg-task-menu { position: absolute; z-index: 55; right: 0; top: 30px; padding: 4px; border: 1px solid #dbdce1; border-radius: 10px; background: var(--cg-page); box-shadow: 0 4px 12px #0001; }

.cg-task-menu .cg-button { display: flex; width: 100%; white-space: nowrap; }



/* Rename dialog, fixed so the sidebar's own scroller cannot clip it. */

.cg-rename-backdrop { position: fixed; inset: 0; z-index: 120; background: #0004; display: grid; place-items: center; }

.cg-rename-dialog { width: min(400px,calc(100vw - 80px)); padding: 20px; border-radius: 18px; background: var(--cg-page); box-shadow: 0 20px 80px #0002; }

.cg-rename-dialog h2 { margin: 0 0 12px; font-size: 16px; font-weight: 500; color: var(--cg-text); }

.cg-rename-input { box-sizing: border-box; display: block; width: 100%; padding: 9px 12px; border: 1px solid #dbdce1; border-radius: 9px; background: var(--cg-page); color: var(--cg-text); font: inherit; }

.cg-rename-error { margin: 8px 0 0; color: #c54545; font-size: 12px; line-height: 17px; }

.cg-rename-note { margin: 8px 0 0; color: var(--cg-muted); font-size: 12px; line-height: 17px; }

.cg-rename-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.cg-rename-actions button { border: 0; border-radius: 8px; padding: 8px 16px; font: inherit; cursor: pointer; }

.cg-rename-cancel { background: var(--cg-hover); color: var(--cg-text); }

.cg-rename-save { background: #4a72d8; color: #fff; }

.cg-rename-save:disabled, .cg-rename-cancel:disabled { opacity: .5; cursor: default; }

/* 人设弹窗复用重命名弹窗的整套类，只补这两条：字段要有自己的标签，正文要能拉大。 */

.cg-rename-field { display: block; margin-top: 10px; }

.cg-rename-field > span { display: block; margin-bottom: 4px; color: var(--cg-muted); font-size: 12px; line-height: 17px; }

.cg-rename-textarea { min-height: 96px; resize: vertical; }

/* 采样参数：原生滑块 + 数字框并排。两边共用同一个草稿值，滑块只负责粗略定位，总高度 18px，

   弹窗高度不因此变长。颜色一律走主题变量 —— 轨道是 --cg-text 与 --cg-page 的混合、滑块本体

   直接用 --cg-text，深色与浅色两侧都成立，没有一个写死的颜色。 */

.cg-sampling-row { display: flex; align-items: center; gap: 10px; }

.cg-sampling-range { flex: 1 1 auto; min-width: 0; width: auto; height: 18px; margin: 0; padding: 0; appearance: none; -webkit-appearance: none; background: transparent; cursor: pointer; }

.cg-sampling-range::-webkit-slider-runnable-track { height: 6px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--cg-text) 16%, var(--cg-page)); }

.cg-sampling-range::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; box-sizing: border-box; width: 14px; height: 14px; margin-top: -4px; border: 0; border-radius: 50%; background: var(--cg-text); box-shadow: 0 0 0 0 transparent; transition: box-shadow 120ms ease; }

.cg-sampling-range::-moz-range-track { height: 6px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--cg-text) 16%, var(--cg-page)); }

.cg-sampling-range::-moz-range-progress { height: 6px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--cg-text) 40%, var(--cg-page)); }

.cg-sampling-range::-moz-range-thumb { box-sizing: border-box; width: 14px; height: 14px; border: 0; border-radius: 50%; background: var(--cg-text); box-shadow: 0 0 0 0 transparent; transition: box-shadow 120ms ease; }

.cg-sampling-range:hover::-webkit-slider-thumb, .cg-sampling-range:focus-visible::-webkit-slider-thumb,

.cg-sampling-range:hover::-moz-range-thumb, .cg-sampling-range:focus-visible::-moz-range-thumb { box-shadow: 0 0 0 4px color-mix(in srgb, var(--cg-text) 18%, transparent); }

.cg-sampling-range:focus-visible { outline: 2px solid #3982fa; outline-offset: 3px; }

.cg-sampling-range:disabled { cursor: default; opacity: .5; }

.cg-sampling-number { flex: 0 0 90px; width: 90px; padding: 7px 8px; text-align: right; }

.cg-rename-field > .cg-sampling-hint { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

@media (prefers-reduced-motion: reduce) {

  .cg-sampling-range::-webkit-slider-thumb, .cg-sampling-range::-moz-range-thumb { transition: none; }

}



/* Align disclosure and new-chat hit areas with the task rows. */

.cg-navigation > .cg-new, .cg-browse > .cg-section-toggle { box-sizing: border-box; width: calc(100% + 12px); margin-left: -6px; margin-right: -6px; padding-left: 8px; padding-right: 8px; border-radius: 10px; justify-content: flex-start; }

.cg-browse > .cg-section-toggle { min-height: 30px; }

.cg-collapsed .cg-navigation > .cg-new { width: 100%; margin-inline: 0; padding-inline: 4px; justify-content: center; }



.cg-model-root:has(.cg-model-popover) { z-index: 100; }

.cg-model-popover { padding-bottom: 16px; background-color: var(--cg-page); isolation: isolate; }

.cg-model-reset { box-sizing: border-box; padding: 4px; }

.cg-model-reset svg { display: block; flex: none; width: 16px; height: 16px; overflow: visible; }

.cg-model-slider-shell { margin-bottom: 2px; }



/* The knob is positioned with `translate: calc((100cqw - 24px) * ratio)`, so this element has to be the

   container those `cqw` units resolve against. Without `container-type` the unit falls back to the

   *viewport* width: the knob then travels one screen-width to the right and leaves the popover entirely —

   the "圆点飞到哪里去了" report. `inline-size` (not `size`) because only the width is queried, and a

   `size` container would have to be given an explicit block size here. */

.cg-model-slider-shell { container-type: inline-size; }



/* Neutralize native/global range tracks; the shell draws the sole visible track. */

.cg-model-slider::-webkit-slider-runnable-track { appearance: none; height: 28px; border: 0; border-radius: 20px; background: transparent !important; box-shadow: none !important; }

.cg-model-slider::-webkit-slider-thumb { margin-top: -2px; }

.cg-model-slider::-moz-range-track { height: 28px; border: 0; background: transparent !important; box-shadow: none !important; }

.cg-model-slider::-moz-range-progress { background: transparent !important; border: 0; box-shadow: none !important; }

.cg-model-slider { background: transparent !important; box-shadow: none !important; outline: none; }



/* First pass: both visible track ends stop at the thumb center, including minimum (`inset: 0 14px`,

   fill `left: 14px`). The full-width override further down replaces both declarations, so the track

   that actually paints runs edge to edge. */

.cg-model-slider-shell { background: transparent !important; box-shadow: none; }

.cg-model-slider-shell::before { content: ''; position: absolute; inset: 0 14px; border-radius: 20px; background: #e8e6e8; }

.cg-model-slider-fill { left: 14px; }

body[data-ds-dark-theme] .cg-model-slider-shell::before { background: #494649; }



/* Full-width track and an independent thumb with two-pixel end overlap. */

.cg-model-slider-shell::before { inset: 4px 0; }

.cg-model-slider-fill { left: 0; }

/* The knob, taken from the reference plugin the owner pointed at (lemonorangeapple/dsh-effort-switcher):

   24px over a thinner track so it overhangs ✓ `corner-shape: round` for a true circle ✓ a centred box

   offset (`margin-left`) instead of `translateX(-50%)` — a percentage plus a half-transform lands the edges

   on fractional device pixels at this display's 1.25 ratio — and no border and no shadow at all. */

.cg-model-thumb { position: absolute; top: 2px; margin-left: -12px; box-sizing: border-box; width: 24px; height: 24px; border: 0; border-radius: 50%; corner-shape: round; background: #fff; box-shadow: none; pointer-events: none; z-index: 3; }

/* The knob grows only while the pointer is over it, and never larger than this.

   It carries `pointer-events: none`, so the "over" state is decided geometrically in the component (the

   knob cannot be hit-tested without swallowing the press that the native range needs to start a drag).

   There used to be a second, larger step while the track was `:active` — that is the step the owner saw as

   the knob growing and being cut off when they dragged it to either end, so it is gone: dragging keeps the

   same 1.08 as hovering, and the ends look like a click-selected tier. */

.cg-model-thumb { transform-origin: 50% 50%; }

.cg-model-thumb[data-over="true"] { transform: scale(1.08); }

/* While the pointer is pressed the knob goes back to its resting size. Hovering and dragging are the same

   pointer-on-knob situation, so without this the drag inherits the hover growth: at either end of the travel

   (centre 12px from the edge) a 1.08 knob overhangs the track by about a pixel, and that is the "it grows

   and sticks to the edge when I drag it" the owner photographed. Dragging now looks exactly like a tier

   that was selected by a click. */

.cg-model-slider-shell:active .cg-model-thumb { transform: none; }

.cg-model-slider::-webkit-slider-thumb { background: transparent; border-color: transparent; box-shadow: none; }

.cg-model-slider::-moz-range-thumb { background: transparent; border-color: transparent; box-shadow: none; }



/* Reference: pill track and a clean maximum-effort gradient. */

.cg-model-slider-shell { border-radius: 14px; }

.cg-model-slider-shell::before, .cg-model-slider-fill { border-radius: 10px; }

.cg-model-slider-shell[data-max="true"] .cg-model-slider-dots { visibility: hidden; }

/* The reference knob is a plain white circle: no outline, just a soft shadow. The plugin already drew a

   circle, but with a 1px grey border that read as a framed square at this size. */

.cg-model-thumb { border: 0; border-radius: 50%; box-shadow: 0 1px 3px #00000026; }

.cg-model-popover[data-ultra="true"] .cg-model-slider-fill { background: linear-gradient(95deg, #5055f5 0%, #bb74ff 58%, #793af5 100%); }



/* Depth ramp. The fill deepens with the tier instead of only changing at Ultra: six stops

   are shared by every model, so three-tier and five-tier effort lists both move

   monotonically, and the top tier — Max — runs into purple without any meteor. Only Ultra

   keeps the animated shower (its rules are keyed on [data-ultra="true"] further down).

   Low starts on a clean light blue: mixing the grey Off stop into it reads as dirty, and

   nothing here lowers opacity — every stop is an opaque colour.

   Declared on the popover, not on `.cg-model-slider-shell` where these are consumed. A custom

   property is inherited downwards only: the popover is the shell's *ancestor*, so a stop declared

   on the shell was invisible to `--cg-glow: var(--cg-e2)` on the popover, and that made the whole

   non-superfast glow invalid. The shell inherits these values unchanged. */

.cg-model-popover {

  --cg-e1: #b3cdff; /* Low: a real blue — a paler tone sat at the track's own lightness

                       and read as grey-blue mud */

  --cg-e2: #86acff;

  --cg-e3: #6488f5; /* Medium */

  --cg-e4: #4a63d8; /* High */

  --cg-e5: #8a4ff0; /* Max -> purple */

}

body[data-ds-dark-theme] .cg-model-popover {

  --cg-e1: #7fa3f5;

  --cg-e2: #6b91ee;

  --cg-e3: #5b80ea;

  --cg-e4: #4f6ae0;

  --cg-e5: #9a5cf5;

}

/* An unknown level id falls back to its bucketed position ... */

.cg-model-slider-shell[data-depth="0"] .cg-model-slider-fill { background: transparent; }

.cg-model-slider-shell[data-depth="1"] .cg-model-slider-fill { background: var(--cg-e1); }

.cg-model-slider-shell[data-depth="2"] .cg-model-slider-fill { background: var(--cg-e2); }

.cg-model-slider-shell[data-depth="3"] .cg-model-slider-fill { background: var(--cg-e3); }

.cg-model-slider-shell[data-depth="4"] .cg-model-slider-fill { background: var(--cg-e4); }

/* ... while an id the ramp knows wins, because it is the tier the model itself names.

   Off fills nothing: a grey stub against a grey track only looked like a stray artefact. */

.cg-model-slider-shell[data-effort="off"] .cg-model-slider-fill { background: transparent; }

.cg-model-slider-shell[data-effort="none"] .cg-model-slider-fill { background: transparent; }

.cg-model-slider-shell[data-effort="minimal"] .cg-model-slider-fill { background: linear-gradient(90deg, var(--cg-e1), var(--cg-e2)); }

.cg-model-slider-shell[data-effort="low"] .cg-model-slider-fill { background: linear-gradient(90deg, var(--cg-e1), var(--cg-e2)); }

.cg-model-slider-shell[data-effort="medium"] .cg-model-slider-fill { background: linear-gradient(90deg, var(--cg-e2), var(--cg-e3)); }

.cg-model-slider-shell[data-effort="high"] .cg-model-slider-fill { background: linear-gradient(90deg, var(--cg-e3), var(--cg-e4)); }

.cg-model-slider-shell[data-effort="xhigh"] .cg-model-slider-fill,

.cg-model-slider-shell[data-effort="max"] .cg-model-slider-fill { background: linear-gradient(90deg, var(--cg-e4), var(--cg-e5)); }

/* Ultra must be declared here, after the depth buckets: the top position is depth 4, so a

   bucket rule placed later silently outranks the gradient and leaves the whole bar blue —

   which is exactly how the purple went missing.

   Shape: a short blue lead-in and a bright purple right end stay put, while a soft deep

   purple shade drifts slowly across the purple middle.

   The shade is its own element rather than a sized background layer: a layer narrower than

   the bar ends mid-falloff, and that cut-off painted a visible seam down each side. As an

   element whose radial radii are exactly half its box, the falloff reaches zero before any

   edge, and only the transform moves. */

.cg-model-slider-shell[data-effort="ultra"] .cg-model-slider-fill {

  background: linear-gradient(90deg, #3f57c4 0%, #6f5ff2 12%, #8a4ff0 42%, #a855f7 74%, #bb74ff 100%);

}

.cg-model-slider-shell[data-effort="ultra"] .cg-model-slider-fill::after {

  content: '';

  position: absolute;

  top: -70%; bottom: -70%; left: 0; width: 62%;

  z-index: 0;

  pointer-events: none;

  background: radial-gradient(ellipse 50% 50% at 50% 50%, #4c1d95e6 0%, #4c1d9545 45%, #4c1d9500 100%);

  animation: cg-model-ultra-drift 12s ease-in-out infinite alternate;

}

/* The shade is 62% of the bar, so its centre sits at translateX * 0.62 + 31%. 11%..50% keeps

   that centre between 38% and 62% of the bar: the deep purple floats in the middle and never

   reaches the blue lead-in on the left or the bright purple end on the right. */

@keyframes cg-model-ultra-drift {

  from { transform: translateX(11%); }

  to { transform: translateX(50%); }

}

/* Max reads purple at the rim, and stays free of the Ultra shower. The rim keys on the

   tier, not on the top position: with a virtual Ultra step appended, Max is the last real

   tier and is deliberately not the maximum position. */

.cg-model-slider-shell[data-effort="xhigh"]:not([data-ultra="true"])::before,

.cg-model-slider-shell[data-effort="max"]:not([data-ultra="true"])::before { box-shadow: inset 0 0 0 1px #8a4ff04d; }

/* Deliberately ungated and deliberately not theme-varied: this dot marks a position the fill has

   not reached on a plain rail, so it is the same neutral in both themes — giving it a dark-mode

   value would make it read as a marker that carries meaning. Both properties are stated so the

   purple ultra glow from the `[data-ultra="true"]` rule cannot leak in while the shell's ultra

   state is off. */

.cg-model-slider-shell:not([data-ultra="true"]) .cg-model-slider-dots span[data-ultra="true"] { background: #b7b4b7; box-shadow: none; }

.cg-model-slider-shell:not([data-ultra="true"]) .cg-model-meteors { display: none; }

/* The dots carry the fill, not a fixed grey: a dot the fill has reached turns white with a

   dark hairline so it stays legible on the pale Low blue as well as on the deep tiers, and

   a dot still ahead stays the track marker. */

.cg-model-slider-dots span[data-on="true"] { background: #fff; box-shadow: 0 0 0 1px #0000002e; }

body[data-ds-dark-theme] .cg-model-slider-dots span { background: #8b8992; }

body[data-ds-dark-theme] .cg-model-slider-dots span[data-on="true"] { background: #fff; box-shadow: 0 0 0 1px #00000052; }



/* The knob travels by `translate`, so that is what animates. This used to name `left`, which the component

   no longer writes — the transition therefore matched nothing and the knob jumped between tiers instead of

   sliding. */

.cg-model-thumb { transition: translate 100ms ease-out, transform 150ms cubic-bezier(.22,.8,.28,1); }

/* The transient Ultra cost notice is longer than any tier name, so it gets its own fit

   instead of stretching the summary pill. */

.cg-model-summary strong[data-notice="true"], .cg-model-trigger-effort[data-notice="true"] { font-size: 11px; letter-spacing: .2px; white-space: nowrap; }

.cg-model-slider-fill { transition: width 100ms ease-out; }

.cg-model-popover { animation: cg-model-enter 120ms ease-out; transform-origin: bottom right; }

@keyframes cg-model-enter { from { opacity: 0; transform: translateY(3px) scale(.985); } to { opacity: 1; transform: translateY(0) scale(1); } }

@media (prefers-reduced-motion: reduce) { .cg-model-thumb, .cg-model-slider-fill { transition: none; } .cg-model-popover { animation: none; } }



/* Reference sidebar typography and disclosure behavior. */

.cg-brand { color: #424242; }

.cg-navigation > .cg-new, .cg-browse > .cg-section-toggle { font-family: var(--dsw-font-family); color: var(--cg-muted); }

.cg-browse > .cg-section-toggle:hover, .cg-browse > .cg-section-toggle:active, .cg-browse > .cg-section-toggle:focus { background: transparent; }

.cg-section-toggle svg { transition: transform 150ms ease-out, opacity 120ms ease-out; opacity: 1; }

.cg-section-toggle[aria-expanded="true"] svg { transform: rotate(90deg); opacity: 0; }

.cg-section-toggle[aria-expanded="true"]:hover svg, .cg-section-toggle[aria-expanded="true"]:focus-visible svg { opacity: 1; }

.cg-browse { overflow: visible; }

.cg-task-row .cg-pinned-row { color: #424242; }

.cg-projects { display: flex; flex-direction: column; gap: 0; }

.cg-projects > .cg-button { width: 100%; min-height: 36px; text-align: left; color: #424242; }

.cg-navigation { min-height: 0; overflow: visible; }

.cg-navigation .cg-browse { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; margin-inline: -6px; padding-inline: 6px; }

.cg-navigation .cg-workspaces[hidden] { display: none; }

body[data-ds-dark-theme] .cg-brand, body[data-ds-dark-theme] .cg-task-row .cg-pinned-row, body[data-ds-dark-theme] .cg-projects > .cg-button { color: var(--cg-text); }

@media (prefers-reduced-motion: reduce) { .cg-section-toggle svg { transition: none; } }



/* Animate a stable wrapper so native SVG styles cannot cancel rotation. */

.cg-disclosure-arrow { display: inline-flex; align-items: center; justify-content: center; width: 13px; height: 13px; flex: none; transform: rotate(0deg); transform-origin: center; opacity: 1; transition: transform 180ms ease, opacity 120ms ease; }

.cg-section-toggle[aria-expanded="true"] .cg-disclosure-arrow { transform: rotate(90deg); opacity: 0; }

.cg-section-toggle[aria-expanded="true"]:hover .cg-disclosure-arrow, .cg-section-toggle[aria-expanded="true"]:focus-visible .cg-disclosure-arrow { opacity: 1; }

.cg-section-toggle .cg-disclosure-arrow svg { display: block; transform: none !important; opacity: 1 !important; transition: none; }



.cg-task-preview-floating { display: block; position: fixed; z-index: 1000; margin: 0; }



.cg-mode-status { margin: 4px 10px 6px; color: #777; font-size: 12px; line-height: 1.5; }

.cg-brand-option:disabled { opacity: .55; cursor: default; }



/* Completed turn disclosure: one shared color for text and arrow. */

html[data-chatgpt-ui] .cg-turn-process {

  display: inline-flex;

