    radial-gradient(1.2px 1.2px at 28% 72%, #e5d9ffcc, transparent),

    radial-gradient(1.8px 1.8px at 39% 22%, #cbb4ff77, transparent),

    radial-gradient(1.2px 1.2px at 47% 26%, #cbb4ff77, transparent),

    radial-gradient(1.1px 1.1px at 55% 74%, #cbb4ffcc, transparent),

    radial-gradient(1.2px 1.2px at 66% 66%, #d9c8ffee, transparent),

    radial-gradient(1.4px 1.4px at 74% 34%, #cbb4ff88, transparent),

    radial-gradient(1.5px 1.5px at 84% 38%, #cbb4ff88, transparent),

