.cg-model-editor { display: flex; flex: 1 1 auto; min-width: 0; align-items: flex-start; gap: 2px; animation: cg-soft-in 140ms cubic-bezier(.22, .8, .28, 1); }

.cg-model-viewer { display: flex; flex: 1 1 auto; min-width: 0; align-items: center; gap: 2px; animation: cg-soft-in 140ms cubic-bezier(.22, .8, .28, 1); }

.cg-menu, .cg-task-menu { animation: cg-soft-in 130ms cubic-bezier(.22, .8, .28, 1); transform-origin: top left; }

