.cg-button, .cg-model-option, .cg-model-rename, .cg-model-alias-save, .cg-model-alias-cancel,

.cg-model-summary, .cg-model-zap, .cg-model-reset, .cg-model-choice, .cg-rail-item, .cg-task-menu .cg-button {

  transition: background-color 140ms cubic-bezier(.22, .8, .28, 1), color 140ms cubic-bezier(.22, .8, .28, 1),

    opacity 140ms cubic-bezier(.22, .8, .28, 1), border-color 140ms cubic-bezier(.22, .8, .28, 1);

