.cg-rail-item { transition: background-color 140ms cubic-bezier(.22, .8, .28, 1), color 140ms cubic-bezier(.22, .8, .28, 1),

  opacity 140ms cubic-bezier(.22, .8, .28, 1), transform 150ms cubic-bezier(.22, .8, .28, 1); }

.cg-task-row .cg-pinned-row { transition: padding-right 170ms cubic-bezier(.22, .8, .28, 1), background-color 140ms cubic-bezier(.22, .8, .28, 1); }

@media (prefers-reduced-motion: reduce) {

  .cg-model-pane, .cg-model-editor, .cg-model-viewer, .cg-menu, .cg-task-menu { animation: none; }

  /* 侧栏的进出场也一并关掉：有人把系统设成减少动态效果，就是不想看这些。 */
  .cg-rail-item, .cg-rail-item svg, .cg-rail-menu-row, .cg-rail-menu-pin, .cg-rail-menu-help { animation: none; }

  .cg-button, .cg-model-option, .cg-model-rename, .cg-model-alias-save, .cg-model-alias-cancel,

  .cg-model-summary, .cg-model-zap, .cg-model-reset, .cg-model-choice, .cg-rail-item,

