@media (prefers-reduced-motion: reduce) {

  html[data-chatgpt-ui] [class*="turnRail"],

  html[data-chatgpt-ui] [class*="turnRail"] *,

  html[data-chatgpt-ui] [class*="turnRail"]::before,

