.cg-model-modes { display: flex; flex-direction: column; gap: 4px; padding: 4px 2px 2px; }

.cg-model-mode { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; padding: 10px 12px; border: 1px solid transparent; border-radius: 12px; background: transparent; color: inherit; font: inherit; text-align: left; cursor: pointer; transition: background-color 120ms ease, border-color 120ms ease; }

