    radial-gradient(1.2px 1.2px at 28% 72%, #ffe6a8cc, transparent),

    radial-gradient(1.8px 1.8px at 39% 22%, #f7c94899, transparent),

    radial-gradient(1.2px 1.2px at 47% 26%, #f7c94899, transparent),

    radial-gradient(1.1px 1.1px at 55% 74%, #f7c948cc, transparent),

    radial-gradient(1.2px 1.2px at 66% 66%, #ffe6a8ee, transparent),

    radial-gradient(1.4px 1.4px at 74% 34%, #ffe6a8cc, transparent),

    radial-gradient(1.5px 1.5px at 84% 38%, #ffe6a8cc, transparent),

