.cg-model-root[data-superfast="true"] .cg-model-popover { --cg-effort-color: #e8a317; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell .cg-model-slider-fill { background: linear-gradient(90deg, #dcb273 0%, #eed3a8 18%, #fdf6e4 38%, #ffe6a8 62%, #f7c948 82%, #e8a317 100%); }

.cg-model-root[data-superfast="true"] .cg-model-trigger-effort[data-ultra="true"] { color: #e8a317; }

.cg-model-root[data-superfast="true"] .cg-model-popover[data-effort="max"] .cg-model-summary strong,

.cg-model-root[data-superfast="true"] .cg-model-popover[data-effort="xhigh"] .cg-model-summary strong { color: #e8a317; }

.cg-model-root[data-superfast="true"] .cg-model-ultra-notice { color: #e8a317; }

body[data-ds-dark-theme] .cg-model-root[data-superfast="true"] .cg-model-ultra-notice { color: #f7ad31; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell::before { box-shadow: inset 0 0 0 1px #f7c9483d; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell[data-ultra="true"] .cg-model-slider-dots span[data-ultra="true"] { background: #e8a317; box-shadow: 0 0 5px #e8a31799; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell[data-ultra="true"] .cg-model-thumb { border-color: #ffe8a8; box-shadow: 0 0 6px #e8a31799, 0 0 16px #c8860d8c, 0 0 0 1px #ffffff99 inset; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell[data-max="true"][data-ultra="true"] .cg-model-thumb { animation: none; }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell .cg-model-meteors { display: block; }

/* Same for the root-scoped 超快 branch. */

.cg-model-root[data-superfast="true"] .cg-model-meteor { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--cg-glow, #ffffff) 45%, #ffffffb8)); }

.cg-model-root[data-superfast="true"] .cg-model-meteors::before { background-image:

    radial-gradient(1.5px 1.5px at 8% 30%, #ffffffdd, transparent),

    radial-gradient(1.2px 1.2px at 20% 68%, #ffedbc, transparent),

    radial-gradient(1.2px 1.2px at 28% 72%, #ffe6a8cc, transparent),

    radial-gradient(1.8px 1.8px at 39% 22%, #ffffffcc, transparent),

    radial-gradient(1.2px 1.2px at 47% 26%, #ffffffcc, transparent),

    radial-gradient(1.1px 1.1px at 55% 74%, #f7c948cc, transparent),

    radial-gradient(1.2px 1.2px at 66% 66%, #ffe6a8ee, transparent),

    radial-gradient(1.4px 1.4px at 74% 34%, #ffffffdd, transparent),

    radial-gradient(1.5px 1.5px at 84% 38%, #ffffffdd, transparent),

    radial-gradient(1.1px 1.1px at 93% 74%, #f7c948cc, transparent); }

.cg-model-root[data-superfast="true"] .cg-model-slider-shell .cg-model-slider-fill::after { background: radial-gradient(ellipse 50% 50% at 50% 50%, #8a4d0de6 0%, #8a4d0d45 45%, #8a4d0d00 100%); }

/* The dark theme carries its own, deeper selectors for the tier names and the glyph colour, so the light-only

   rules above are not enough: the owner's panel is dark, which is why the first attempt looked like a no-op. */

body[data-ds-dark-theme] .cg-model-root[data-superfast="true"] .cg-model-popover { --cg-effort-color: #f0b429; }

body[data-ds-dark-theme] .cg-model-root[data-superfast="true"] .cg-model-trigger-effort[data-ultra="true"],

body[data-ds-dark-theme] .cg-model-root[data-superfast="true"] .cg-model-popover[data-effort="max"] .cg-model-summary strong,

