.cg-model-root[data-superfast="true"] .cg-model-zap[data-on="true"] .cg-model-zap-glyph { filter: drop-shadow(0 0 5px #f7c9488c); }

body[data-ds-dark-theme] .cg-model-root[data-superfast="true"] .cg-model-slider-shell[data-ultra="true"] .cg-model-slider-dots span[data-ultra="true"] { background: #f0b429; box-shadow: 0 0 5px #f0b42999; }

