.cg-model-root[data-superfast="true"] .cg-model-slider-shell[data-ultra="true"]::after { background-size: 220% 100%; background-repeat: no-repeat; background-image: linear-gradient(105deg, #ffffff00 44%, #f0d9a88f 50%, #ffe9b09e 56%, #ffffff00 62%); }



