/* terminal-native-paths-v1: draw strokes directly; never paint a masked solid square. */
svg:has(> path[d="M3.5 4.5L7.5 8l-4 3.5"]) { border: 0; border-radius: 0; box-sizing: border-box; padding: 0; width: 16px; height: 16px; flex-shrink: 0; background: transparent; -webkit-mask: none; mask: none; }
svg:has(> path[d="M3.5 4.5L7.5 8l-4 3.5"]) > path { opacity: 1; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; }
svg:has(> path[d="M3.5 4.5L7.5 8l-4 3.5"]) > path:first-child { d: path("M3.5 1H12.5A2.5 2.5 0 0 1 15 3.5V12.5A2.5 2.5 0 0 1 12.5 15H3.5A2.5 2.5 0 0 1 1 12.5V3.5A2.5 2.5 0 0 1 3.5 1Z"); stroke-width: 1.5; }
svg:has(> path[d="M3.5 4.5L7.5 8l-4 3.5"]) > path:nth-child(2) { d: path("M4.5 5.5 7.5 8 4.5 10.5M9 11H12"); stroke-width: 1.75; }

