/* 审查者后台：设置里的一页，逐条显示判定过程。 */
.cg-review-log { display: flex; flex-direction: column; gap: 10px; font-size: 13px; line-height: 20px; }
.cg-review-head { display: flex; flex-direction: column; gap: 8px; }
.cg-review-actions { display: flex; gap: 8px; }
.cg-review-item { border: 1px solid var(--cg-border, rgba(127,127,127,.25)); border-radius: 10px; overflow: hidden; }
.cg-review-summary { display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 12px; background: none; border: 0; color: var(--cg-text); cursor: pointer; text-align: left; font-size: 13px; }
.cg-review-summary:hover { background: var(--cg-hover); }
.cg-review-decision { flex: none; padding: 1px 8px; border-radius: 999px; font-size: 12px; }
.cg-review-ask { background: rgba(217,119,87,.18); color: #d97757; }
.cg-review-allow { background: rgba(56,161,105,.16); color: #38a169; }
.cg-review-other { background: rgba(127,127,127,.18); color: var(--cg-muted); }
.cg-review-tool { font-weight: 600; }
.cg-review-time { color: var(--cg-muted); font-size: 12px; }
.cg-review-rules { padding: 1px 7px; border-radius: 999px; background: rgba(127,127,127,.16); font-size: 12px; }
.cg-review-duration { color: var(--cg-muted); font-size: 12px; margin-left: auto; }
.cg-review-body { padding: 4px 12px 12px; display: flex; flex-direction: column; gap: 10px; }
.cg-review-field { display: flex; flex-direction: column; gap: 4px; }
.cg-review-field-label { color: var(--cg-muted); font-size: 12px; }
.cg-review-field p { margin: 0; white-space: pre-wrap; word-break: break-word; }
.cg-review-field pre { margin: 0; padding: 8px 10px; border-radius: 8px; background: var(--cg-hover); white-space: pre-wrap; word-break: break-word; font-size: 12px; line-height: 18px; max-height: 320px; overflow: auto; }
